<?php
namespace App\Application\Claims;
use App\Application\Audit\AuditWriter;use App\Application\Events\OutboxWriter;use App\Application\Shared\CanonicalJson;use App\Models\{Claim,User};use Illuminate\Support\Facades\DB;use Illuminate\Support\Str;use Illuminate\Validation\ValidationException;
final class ClaimCarrierExchangeService{public function __construct(private CanonicalJson$json,private AuditWriter$audit,private OutboxWriter$outbox){}public function queue(Claim$c,string$type,array$payload,string$key,User$actor):object{return DB::transaction(function()use($c,$type,$payload,$key,$actor){$c=Claim::whereKey($c->id)->lockForUpdate()->firstOrFail();if($c->tenant_id!==app(\App\Domain\Tenancy\TenantContext::class)->id())abort(404);if($x=DB::table('carrier_exchange_messages')->where(['carrier_id'=>$c->policy->carrier_id,'correlation_id'=>$key,'direction'=>'OUTBOUND'])->first()){if(!hash_equals($x->payload_hash,$this->json->hash($payload)))throw ValidationException::withMessages(['idempotency_key'=>__('wave7.idempotency_conflict')]);return$x;}$id=(string)Str::uuid();DB::table('carrier_exchange_messages')->insert(['id'=>$id,'carrier_id'=>$c->policy->carrier_id,'claim_id'=>$c->id,'direction'=>'OUTBOUND','message_type'=>$type,'correlation_id'=>$key,'status'=>'QUEUED','payload'=>json_encode($payload,JSON_THROW_ON_ERROR),'payload_hash'=>$this->json->hash($payload),'attempt_count'=>0,'created_at'=>now(),'updated_at'=>now()]);$this->audit->record('claim.carrier_message.queued','carrier_exchange_message',$id,['claim_id'=>$c->id]);$this->outbox->record('claim.carrier_message.queued','carrier_exchange_message',$id,['claim_id'=>$c->id]);return DB::table('carrier_exchange_messages')->find($id);});}public function markFailure(Claim$c,string$id,string$reason):void{$changed=DB::table('carrier_exchange_messages')->where(['id'=>$id,'claim_id'=>$c->id])->whereIn('status',['QUEUED','SENT','RETRY_PENDING'])->update(['status'=>'RETRY_PENDING','failure_reason'=>$reason,'attempt_count'=>DB::raw('attempt_count + 1'),'next_attempt_at'=>now()->addMinutes(5),'updated_at'=>now()]);if(!$changed)abort(404);}public function acknowledge(Claim$c,string$id,string$external):void{DB::transaction(function()use($c,$id,$external){$message=DB::table('carrier_exchange_messages')->where(['id'=>$id,'claim_id'=>$c->id])->whereIn('status',['QUEUED','SENT','RETRY_PENDING'])->lockForUpdate()->first();if(!$message)abort(404);DB::table('carrier_exchange_messages')->where('id',$id)->update(['status'=>'ACKNOWLEDGED','external_reference'=>$external,'acknowledged_at'=>now(),'next_attempt_at'=>null,'failure_reason'=>null,'updated_at'=>now()]);if(in_array($message->message_type,['CLAIM_DECISION_REQUEST','CLAIM_SUBMISSION'],true))Claim::whereKey($c->id)->update(['carrier_reference'=>$external]);$this->audit->record('claim.carrier_message.acknowledged','carrier_exchange_message',$id,['claim_id'=>$c->id,'external_reference'=>$external]);});}}
